pm.test("GET users returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("GET users response uses JSON content type", function () {
    const contentType = pm.response.headers.get("Content-Type") || "";
    pm.expect(contentType).to.match(/application\/json/i);
});

pm.test("GET users response has status 200 and a users array", function () {
    pm.expect(responseBody).to.be.an("object");
    pm.expect(responseBody && responseBody.status).to.eql(200);
    pm.expect(responseBody && responseBody.users).to.be.an("array");
});

pm.test("Each user has the expected fields and data types", function () {
    pm.expect(responseBody && responseBody.users).to.be.an("array");
    (responseBody.users || []).forEach(function (user) {
        pm.expect(user).to.be.an("object");
        pm.expect(user.userId).to.be.a("string").and.not.empty;
        pm.expect(user.username).to.be.a("string").and.not.empty;
        pm.expect(user.age).to.be.a("number");
    });
});
